package com.twelvemonkeys.imageio.plugins.pcx;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;

class BitRotatorTest {

    @Test
    void rotatesTopLeftBitToTopRight() {
        byte[] src = new byte[8];
        src[0] = (byte) 0x80; // (x=0, y=0)

        byte[] dst = new byte[8];
        BitRotator.bitRotateCW(src, 0, 1, dst, 0, 1);

        // Clockwise rotation maps (0, 0) to (7, 0).
        assertArrayEquals(new byte[]{0x01, 0, 0, 0, 0, 0, 0, 0}, dst);
    }

    @Test
    void rotatesLeftColumnToTopRow() {
        byte[] src = new byte[8];
        for (int i = 0; i < 8; i++) {
            src[i] = (byte) 0x80; // first column
        }

        byte[] dst = new byte[8];
        BitRotator.bitRotateCW(src, 0, 1, dst, 0, 1);

        assertArrayEquals(new byte[]{(byte) 0xFF, 0, 0, 0, 0, 0, 0, 0}, dst);
    }

    @Test
    void rotatesLastRowToLeftColumn() {
        byte[] src = new byte[8];
        src[7] = (byte) 0xFF;

        byte[] dst = new byte[8];
        BitRotator.bitRotateCW(src, 0, 1, dst, 0, 1);

        assertArrayEquals(new byte[]{(byte) 0x80, (byte) 0x80, (byte) 0x80, (byte) 0x80,
                (byte) 0x80, (byte) 0x80, (byte) 0x80, (byte) 0x80}, dst);
    }

    @Test
    void rotatingAntiDiagonalProducesMainDiagonal() {
        byte[] src = new byte[8];
        for (int i = 0; i < 8; i++) {
            src[i] = (byte) (1 << (7 - i)); // anti-diagonal
        }

        byte[] dst = new byte[8];
        BitRotator.bitRotateCW(src, 0, 1, dst, 0, 1);

        byte[] expected = new byte[8];
        for (int i = 0; i < 8; i++) {
            expected[i] = (byte) (1 << i);
        }
        assertArrayEquals(expected, dst);
    }

    @Test
    void fullTileIsInvariant() {
        byte[] src = new byte[8];
        java.util.Arrays.fill(src, (byte) 0xFF);

        byte[] dst = new byte[8];
        BitRotator.bitRotateCW(src, 0, 1, dst, 0, 1);

        assertArrayEquals(src, dst);
    }

    @Test
    void respectsSourcePositionAndRowStep() {
        byte[] src = new byte[16];
        src[1] = (byte) 0x80;
        // Other source rows are all zero, with two bytes between them.

        byte[] dst = new byte[8];
        BitRotator.bitRotateCW(src, 1, 2, dst, 0, 1);

        assertArrayEquals(new byte[]{0x01, 0, 0, 0, 0, 0, 0, 0}, dst);
    }

    @Test
    void respectsDestinationPositionAndRowStep() {
        byte[] src = new byte[8];
        src[0] = (byte) 0x80;

        byte[] dst = new byte[20];
        java.util.Arrays.fill(dst, (byte) 0x7F);
        BitRotator.bitRotateCW(src, 0, 1, dst, 2, 2);

        assertArrayEquals(new byte[]{
                0x7F, 0x7F,
                0x01, 0x7F,
                0x00, 0x7F,
                0x00, 0x7F,
                0x00, 0x7F,
                0x00, 0x7F,
                0x00, 0x7F,
                0x00, 0x7F,
                0x00, 0x7F,
                0x7F, 0x7F
        }, dst);
    }

    @Test
    void writesOnlyRowsThatFitInDestination() {
        byte[] src = new byte[8];
        src[0] = (byte) 0x80;

        byte[] dst = new byte[]{0x7F, 0x7F};

        assertDoesNotThrow(() -> BitRotator.bitRotateCW(src, 0, 1, dst, 0, 1));
        assertArrayEquals(new byte[]{0x01, 0x00}, dst);
    }
