package com.twelvemonkeys.imageio.plugins.pcx;

import org.junit.jupiter.api.Test;

import java.awt.image.IndexColorModel;

import static org.junit.jupiter.api.Assertions.assertEquals;

class CGAColorModelTest {

    @Test
    void monochromeUsesBackgroundForZeroAndBlackForOne() {
        IndexColorModel model = CGAColorModel.create(new byte[]{0x50, 0, 0, 0}, 1);

        assertEquals(1, model.getPixelSize());
        assertEquals(2, model.getMapSize());
        assertEquals(0xFFAA00AA, model.getRGB(0)); // CGA background 5: magenta
        assertEquals(0xFF000000, model.getRGB(1)); // foreground is always black
    }

    @Test
    void monochromeOnlyNeedsTheBackgroundByte() {
        IndexColorModel model = CGAColorModel.create(new byte[]{0x20}, 1);

        assertEquals(0xFF00AA00, model.getRGB(0)); // CGA background 2: green
        assertEquals(0xFF000000, model.getRGB(1));
    }

    @Test
    void twoBitPaletteFlagsProduceLightCyanMagentaWhite() {
        IndexColorModel model = CGAColorModel.create(new byte[]{0x00, 0, 0, (byte) 0xE0}, 2);

        assertEquals(2, model.getPixelSize());
        assertEquals(4, model.getMapSize());
        assertEquals(0xFF000000, model.getRGB(0));
        assertEquals(0xFF55FFFF, model.getRGB(1));
        assertEquals(0xFFFF55FF, model.getRGB(2));
        assertEquals(0xFFFFFFFF, model.getRGB(3));
    }

    @Test
    void twoBitPaletteWithoutColorBurstProducesRedInsteadOfMagenta() {
        IndexColorModel model = CGAColorModel.create(new byte[]{0x00, 0, 0, 0x60}, 2);

        assertEquals(0xFF55FFFF, model.getRGB(1));
        assertEquals(0xFFFF5555, model.getRGB(2));
        assertEquals(0xFFFFFFFF, model.getRGB(3));
    }

    @Test
    void twoBitPaletteWithoutIntensityProducesDarkColors() {
        IndexColorModel model = CGAColorModel.create(new byte[]{0x00, 0, 0, (byte) 0xC0}, 2);

        assertEquals(0xFF00AAAA, model.getRGB(1));
        assertEquals(0xFFAA00AA, model.getRGB(2));
        assertEquals(0xFFAAAAAA, model.getRGB(3));
    }

    @Test
    void twoBitPaletteWithoutPaletteFlagUsesFixedIntenseColors() {
        IndexColorModel model = CGAColorModel.create(new byte[]{0x00, 0, 0, 0x20}, 2);

        assertEquals(0xFF55FF55, model.getRGB(1));
        assertEquals(0xFFFF5555, model.getRGB(2));
        assertEquals(0xFFFFFF55, model.getRGB(3));
    }

    @Test
    void twoBitPaletteWithoutPaletteOrIntensityUsesFixedDarkColors() {
        IndexColorModel model = CGAColorModel.create(new byte[]{0x00, 0, 0, 0x00}, 2);

        assertEquals(0xFF00AA00, model.getRGB(1));
        assertEquals(0xFFAA0000, model.getRGB(2));
        assertEquals(0xFFAA5500, model.getRGB(3));
    }

    @Test
    void backgroundColorComesFromHighNibbleOfFirstByte() {
        IndexColorModel model = CGAColorModel.create(new byte[]{(byte) 0xA0, 0, 0, 0}, 2);

        assertEquals(0xFF55FF55, model.getRGB(0)); // CGA background A: light green
        assertEquals(0xFF00AA00, model.getRGB(1));
    }
}
package com.twelvemonkeys.imageio.plugins.pcx;

import org.junit.jupiter.api.Test;

import javax.imageio.IIOException;
import javax.imageio.stream.ImageInputStream;
import java.awt.image.IndexColorModel;
import java.io.IOException;
import java.nio.ByteOrder;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class PCXHeaderTest {

    @Test
    void readsAllDocumentedHeaderFields() throws IOException {
        byte[] palette = PCXTestSupport.palette(0xFF0000, 0x00FF00, 0x0000FF);
        byte[] data = PCXTestSupport.header(5, 1, 8, 10, 20, 29, 39, 300, 200, palette, 3, 20, 2);

        PCXHeader header = read(data);

        assertEquals(5, header.getVersion());
        assertEquals(1, header.getCompression());
        assertEquals(8, header.getBitsPerPixel());
        assertEquals(20, header.getWidth());
        assertEquals(20, header.getHeight());
        assertEquals(3, header.getChannels());
        assertEquals(20, header.getBytesPerLine());
    }

    @Test
    void widthAndHeightAccountForStartCoordinates() throws IOException {
        byte[] data = PCXTestSupport.header(5, 0, 8, 7, 11, 16, 30, 72, 72, null, 1, 10, 1);

        PCXHeader header = read(data);

        assertEquals(10, header.getWidth());
        assertEquals(20, header.getHeight());
    }

    @Test
    void readsUnsignedHeaderValues() throws IOException {
        byte[] data = PCXTestSupport.header(255, 255, 255, 0, 0, 65535, 65535, 65535, 65535, null, 255, 65535, 65535);

        PCXHeader header = read(data);

        assertEquals(255, header.getVersion());
        assertEquals(255, header.getCompression());
        assertEquals(255, header.getBitsPerPixel());
        assertEquals(65536, header.getWidth());
        assertEquals(65536, header.getHeight());
        assertEquals(255, header.getChannels());
        assertEquals(65535, header.getBytesPerLine());
    }

    @Test
    void rejectsWrongMagic() {
        byte[] data = PCXTestSupport.header(5, 1, 8, 16, 16, null, 1, 16);
        data[0] = 0x0B;

        IIOException exception = assertThrows(IIOException.class, () -> read(data));
        assertTrue(exception.getMessage().contains("Not a PCX image"), exception.getMessage());
    }

    @Test
    void triviaIsExposedInToString() throws IOException {
        byte[] palette = PCXTestSupport.palette(0x112233);
        byte[] data = PCXTestSupport.header(5, 1, 8, 0, 0, 15, 7, 72, 72, palette, 3, 16, 3);

        String string = read(data).toString();

        assertTrue(string.contains("version=5"), string);
        assertTrue(string.contains("compression=1"), string);
        assertTrue(string.contains("bitsPerPixel=8"), string);
        assertTrue(string.contains("width=16"), string);
        assertTrue(string.contains("height=8"), string);
        assertTrue(string.contains("channels=3"), string);
        assertTrue(string.contains("bytesPerLine=16"), string);
        // Palette type bit 1 is masked away by the reader.
        assertTrue(string.contains("paletteInfo=2"), string);
        assertTrue(string.contains("palette=[17, 34, 51"), string);
    }

    @Test
    void cgaMode4PaletteUsesBackgroundAndFlagBytes() throws IOException {
        byte[] palette = PCXTestSupport.blankPalette();
        palette[0] = 0x13; // background 1 (blue)
        palette[3] = (byte) 0xA4; // burst=1, palette=0, intensity=1
        byte[] data = PCXTestSupport.header(5, 1, 2, 0, 0, 319, 199, 320, 200, palette, 1, 80, 1);

        IndexColorModel model = read(data).getEGAPalette();

        assertEquals(4, model.getMapSize());
        assertEquals(0xFF0000AA, model.getRGB(0)); // blue background
        assertEquals(0xFF55FF55, model.getRGB(1));
        assertEquals(0xFFFF5555, model.getRGB(2));
        assertEquals(0xFFFFFF55, model.getRGB(3));
    }

    @Test
    void cgaMode5PaletteUsesBackgroundFromHeader() throws IOException {
        byte[] palette = PCXTestSupport.blankPalette();
        palette[0] = 0x30; // background 3 (cyan)
        byte[] data = PCXTestSupport.header(5, 1, 1, 0, 0, 319, 199, 320, 200, palette, 1, 80, 1);

        IndexColorModel model = read(data).getEGAPalette();

        assertEquals(2, model.getMapSize());
        assertEquals(0xFF00AAAA, model.getRGB(0));
        assertEquals(0xFF000000, model.getRGB(1));
    }

    @Test
    void cgaMode6PaletteUsesBackgroundFromHeader() throws IOException {
        byte[] palette = PCXTestSupport.blankPalette();
        palette[0] = 0x20; // background 2 (green)
        byte[] data = PCXTestSupport.header(5, 1, 1, 0, 0, 639, 199, 640, 200, palette, 1, 80, 1);

        IndexColorModel model = read(data).getEGAPalette();

        assertEquals(2, model.getMapSize());
        assertEquals(0xFF00AA00, model.getRGB(0));
        assertEquals(0xFF000000, model.getRGB(1));
    }

    @Test
    void preVersion4MonochromeUsesBlackAndWhite() throws IOException {
        byte[] palette = PCXTestSupport.palette(0xFF0000, 0x00FF00);
        byte[] data = PCXTestSupport.header(3, 1, 1, 16, 16, palette, 1, 2);

        IndexColorModel model = read(data).getEGAPalette();

        assertEquals(2, model.getMapSize());
        assertEquals(0xFF000000, model.getRGB(0));
        assertEquals(0xFFFFFFFF, model.getRGB(1));
    }

    @Test
    void emptyPaletteIsTreatedAsDummyPalette() throws IOException {
        byte[] data = PCXTestSupport.header(5, 1, 1, 16, 16, PCXTestSupport.blankPalette(), 1, 2);

        IndexColorModel model = read(data).getEGAPalette();

        assertEquals(2, model.getMapSize());
        assertEquals(0xFF000000, model.getRGB(0));
        assertEquals(0xFFFFFFFF, model.getRGB(1));
    }

    @Test
    void photoshopPaletteIsTreatedAsDummyPalette() throws IOException {
        byte[] palette = new byte[48];
        for (int i = 0; i < 16; i++) {
            palette[i * 3] = palette[i * 3 + 1] = palette[i * 3 + 2] = (byte) (15 - i);
        }
        byte[] data = PCXTestSupport.header(5, 1, 1, 32, 32, palette, 1, 2);

        IndexColorModel model = read(data).getEGAPalette();

        assertEquals(0xFF000000, model.getRGB(0));
        assertEquals(0xFFFFFFFF, model.getRGB(1));
    }

    @Test
    void realMonochromePaletteIsReadFromHeader() throws IOException {
        byte[] palette = PCXTestSupport.palette(0x112233, 0x445566);
        byte[] data = PCXTestSupport.header(5, 1, 1, 32, 32, palette, 1, 2);

        IndexColorModel model = read(data).getEGAPalette();

        assertEquals(2, model.getMapSize());
        assertEquals(0xFF112233, model.getRGB(0));
        assertEquals(0xFF445566, model.getRGB(1));
    }

    @Test
    void twoBitPlanesUseFourEntryPalette() throws IOException {
        byte[] palette = PCXTestSupport.palette(0x010203, 0x040506, 0x070809, 0x0A0B0C);
        byte[] data = PCXTestSupport.header(5, 1, 1, 8, 1, palette, 2, 1);

        IndexColorModel model = read(data).getEGAPalette();

        assertEquals(4, model.getMapSize());
        assertEquals(0xFF010203, model.getRGB(0));
        assertEquals(0xFF0A0B0C, model.getRGB(3));
    }

    @Test
    void fourBitIndexedImageUsesSixteenEntryPalette() throws IOException {
        int[] colors = new int[16];
        for (int i = 0; i < colors.length; i++) {
            colors[i] = i * 0x010203;
        }
        byte[] data = PCXTestSupport.header(5, 1, 4, 10, 1, PCXTestSupport.palette(colors), 1, 10);

        IndexColorModel model = read(data).getEGAPalette();

        assertEquals(4, model.getPixelSize());
        assertEquals(16, model.getMapSize());
        for (int i = 0; i < 16; i++) {
            assertEquals(0xFF000000 | colors[i], model.getRGB(i));
        }
    }

    private static PCXHeader read(byte[] data) throws IOException {
        try (ImageInputStream input = PCXTestSupport.input(data)) {
            input.setByteOrder(ByteOrder.LITTLE_ENDIAN);
            return PCXHeader.read(input);
        }
    }
}
package com.twelvemonkeys.imageio.plugins.pcx;

import org.junit.jupiter.api.Test;

import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.stream.ImageInputStream;
import java.io.EOFException;
import java.io.IOException;
import java.util.Arrays;
import java.util.Iterator;
import java.util.Locale;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class PCXImageReaderSpiTest {

    private final PCXImageReaderSpi spi = new PCXImageReaderSpi();

    @Test
    void acceptsSupportedVersionCompressionAndBitsPerPixelCombinations() throws IOException {
        int[] versions = {PCX.VERSION_2_5, PCX.VERSION_2_8_PALETTE, PCX.VERSION_2_8_NO_PALETTE,
                PCX.VERSION_2_X_WINDOWS, PCX.VERSION_3};
        int[] compressions = {PCX.COMPRESSION_NONE, PCX.COMPRESSION_RLE};
        int[] bitsPerPixel = {1, 2, 4, 8};

        for (int version : versions) {
            for (int compression : compressions) {
                for (int bpp : bitsPerPixel) {
                    byte[] data = {PCX.MAGIC, (byte) version, (byte) compression, (byte) bpp};
                    try (ImageInputStream input = PCXTestSupport.input(data)) {
                        assertTrue(spi.canDecodeInput(input),
                                "Expected support for version=" + version + ", compression=" + compression + ", bpp=" + bpp);
                        assertEquals(0, input.getStreamPosition(), "canDecodeInput must restore the stream position");
                    }
                }
            }
        }
    }

    @Test
    void rejectsUnsupportedVersions() throws IOException {
        for (int version : new int[]{1, 6, 127, 255}) {
            assertFalse(canDecode(PCX.MAGIC, (byte) version, (byte) 1, (byte) 8),
                    "Unexpected support for version " + version);
        }
    }

    @Test
    void rejectsUnsupportedCompression() throws IOException {
        for (int compression : new int[]{2, 3, 127, 255}) {
            assertFalse(canDecode(PCX.MAGIC, (byte) 5, (byte) compression, (byte) 8),
                    "Unexpected support for compression " + compression);
        }
    }

    @Test
    void rejectsUnsupportedBitsPerPixel() throws IOException {
        for (int bpp : new int[]{0, 3, 5, 6, 7, 16, 24, 255}) {
            assertFalse(canDecode(PCX.MAGIC, (byte) 5, (byte) 1, (byte) bpp),
                    "Unexpected support for bits per pixel " + bpp);
        }
    }

    @Test
    void rejectsWrongMagic() throws IOException {
        assertFalse(canDecode((byte) 0x0B, (byte) 5, (byte) 1, (byte) 8));
        assertFalse(canDecode((byte) 0x00, (byte) 5, (byte) 1, (byte) 8));
        assertFalse(canDecode((byte) 0x89, (byte) 5, (byte) 1, (byte) 8));
    }

    @Test
    void rejectsNonStreamInput() throws IOException {
        assertFalse(spi.canDecodeInput(new byte[]{PCX.MAGIC, 5, 1, 8}));
        assertFalse(spi.canDecodeInput("not an image stream"));
        assertFalse(spi.canDecodeInput(null));
    }

    @Test
    void throwsEofForTruncatedHeader() {
        assertThrows(EOFException.class, () -> spi.canDecodeInput(PCXTestSupport.input(new byte[0])));
        assertThrows(EOFException.class, () -> spi.canDecodeInput(PCXTestSupport.input(new byte[]{PCX.MAGIC})));
        assertThrows(EOFException.class, () -> spi.canDecodeInput(PCXTestSupport.input(new byte[]{PCX.MAGIC, 5})));
        assertThrows(EOFException.class, () -> spi.canDecodeInput(PCXTestSupport.input(new byte[]{PCX.MAGIC, 5, 1})));
    }

    @Test
    void decodesInputStartingAtCurrentStreamPosition() throws IOException {
        byte[] data = {0x55, 0x66, PCX.MAGIC, 5, 1, 8};

        try (ImageInputStream input = PCXTestSupport.input(data)) {
            input.seek(2);
            assertTrue(spi.canDecodeInput(input));
            assertEquals(2, input.getStreamPosition(), "Position should be restored to the mark");
        }
    }

    @Test
    void createsPCXImageReader() throws IOException {
        ImageReader reader = spi.createReaderInstance();
        try {
            assertTrue(reader instanceof PCXImageReader);
            assertSame(spi, reader.getOriginatingProvider());
        }
        finally {
            reader.dispose();
        }

        ImageReader withExtension = spi.createReaderInstance("extension");
        try {
            assertTrue(withExtension instanceof PCXImageReader);
        }
        finally {
            withExtension.dispose();
        }
    }

    @Test
    void exposesProviderMetadata() {
        assertArrayEquals(new String[]{"pcx", "PCX"}, spi.getFormatNames());
        assertArrayEquals(new String[]{"pcx"}, spi.getFileSuffixes());
        assertArrayEquals(new String[]{"image/pcx", "image/x-pcx"}, spi.getMIMETypes());
        assertTrue(Arrays.asList(spi.getInputTypes()).contains(ImageInputStream.class));
        assertEquals("ZSoft PC Paintbrush (PCX) image reader", spi.getDescription(Locale.ENGLISH));
        assertEquals("ZSoft PC Paintbrush (PCX) image reader", spi.getDescription(Locale.GERMANY));
        assertEquals("TwelveMonkeys", spi.getVendorName());
        assertNotNull(spi.getVersion());
    }

    @Test
    void isDiscoverableThroughImageIO() {
        Iterator<ImageReader> readers = ImageIO.getImageReadersByFormatName("pcx");
        boolean found = false;
        while (readers.hasNext()) {
            if (readers.next() instanceof PCXImageReader) {
                found = true;
            }
        }
        assertTrue(found, "PCXImageReaderSpi should be registered as an ImageIO service");
    }

    private boolean canDecode(byte... data) throws IOException {
        try (ImageInputStream input = PCXTestSupport.input(data)) {
            return spi.canDecodeInput(input);
        }
    }
}
