        byte[] header = PCXTestSupport.header(5, PCX.COMPRESSION_NONE, 8, 4, 2,
                PCXTestSupport.blankPalette(), 1, 4);
        byte[] body = {
                0, 64, (byte) 128, (byte) 255,
                (byte) 255, (byte) 128, 64, 0
        };

        PCXImageReader reader = PCXTestSupport.reader(PCXTestSupport.pcx(header, body));
        try {
            assertEquals(4, reader.getWidth(0));
            assertEquals(2, reader.getHeight(0));
            assertEquals(1, reader.getNumImages(true));

            ImageTypeSpecifier rawType = reader.getRawImageType(0);
            assertEquals(ColorSpace.TYPE_GRAY, rawType.getColorModel().getColorSpace().getType());
            assertEquals(1, rawType.getNumBands());

            BufferedImage image = reader.read(0);
            assertEquals(4, image.getWidth());
            assertEquals(2, image.getHeight());
            assertArrayEquals(new int[]{0, 64, 128, 255}, rowSamples(image, 0));
