    @Test
    void readsOneBitTwoPlaneImageExactly() throws IOException {
        byte[] palette = PCXTestSupport.palette(0xFF0000, 0x00FF00, 0x0000FF, 0xFFFFFF);
        byte[] header = PCXTestSupport.header(5, PCX.COMPRESSION_NONE, 1, 16, 1, palette, 2, 2);
        byte[] body = {(byte) 0x80, 0x00, 0x01, 0x00};

        PCXImageReader reader = PCXTestSupport.reader(PCXTestSupport.pcx(header, body));
        try {
            IndexColorModel model = assertInstanceOf(IndexColorModel.class,
                    reader.getRawImageType(0).getColorModel());
            assertEquals(4, model.getMapSize());

            BufferedImage image = reader.read(0);
            // Plane 0 has its top bit set at x=0; plane 1 has its low bit set at x=7.
            // Together they should decode to palette indices 1 and 2 at those columns.
            assertArrayEquals(new int[]{1, 0, 0, 0, 0, 0, 0, 2, 0, 0, 0, 0, 0, 0, 0, 0}, rowSamples(image, 0));
            assertEquals(0xFF00FF00, image.getRGB(0, 0));
            assertEquals(0xFFFF0000, image.getRGB(1, 0));
            assertEquals(0xFF0000FF, image.getRGB(7, 0));
        }
        finally {
            PCXTestSupport.dispose(reader);
        }
    }

