    private static int[] rowSamples(BufferedImage image, int y) {
        int[] samples = new int[image.getWidth()];
        for (int x = 0; x < samples.length; x++) {
            samples[x] = image.getRaster().getSample(x, y, 0);
        }
        return samples;
    }


    private static Node find(Node node, String name) {
        if (node == null) {
            return null;
        }
        if (name.equals(node.getNodeName())) {
            return node;
        }
        for (Node child = node.getFirstChild(); child != null; child = child.getNextSibling()) {
            Node found = find(child, name);
            if (found != null) {
                return found;
            }
        }
        return null;
    }

    private static String attribute(Node node, String name) {
        assertNotNull(node, "Missing metadata node");
        return node.getAttributes().getNamedItem(name).getNodeValue();
    }
}
package com.twelvemonkeys.imageio.plugins.pcx;

import com.twelvemonkeys.imageio.util.ImageTypeSpecifiers;
import org.junit.jupiter.api.Test;
import org.w3c.dom.Node;

import javax.imageio.ImageTypeSpecifier;
import javax.imageio.metadata.IIOMetadata;
import javax.imageio.metadata.IIOMetadataFormatImpl;
import javax.imageio.stream.ImageInputStream;
import java.awt.color.ColorSpace;
import java.awt.image.DataBuffer;
import java.io.IOException;
import java.nio.ByteOrder;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;

class PCXMetadataTest {

    private static final ImageTypeSpecifier GRAY =
            ImageTypeSpecifiers.createGrayscale(8, DataBuffer.TYPE_BYTE);

    @Test
    void reportsUnknownCompressionName() throws IOException {
        PCXMetadata metadata = new PCXMetadata(GRAY, header(5, 2, 8, 1));

        Node root = standardTree(metadata);

        assertEquals("Unknown", attribute(find(root, "CompressionTypeName"), "value"));
        assertEquals("TRUE", attribute(find(root, "Lossless"), "value"));
    }

    @Test
    void reportsPixelInterleavedForSingleChannelImage() throws IOException {
        PCXMetadata metadata = new PCXMetadata(GRAY, header(3, PCX.COMPRESSION_NONE, 8, 1));

        Node root = standardTree(metadata);

        assertNull(find(root, "Compression"));
        assertEquals("PixelInterleaved", attribute(find(root, "PlanarConfiguration"), "value"));
        assertEquals("3", attribute(find(root, "FormatVersion"), "value"));
    }

    @Test
    void reportsLineInterleavedForMultiChannelImage() throws IOException {
        ImageTypeSpecifier rgb = ImageTypeSpecifiers.createBanded(
                ColorSpace.getInstance(ColorSpace.CS_sRGB),
                new int[]{0, 1, 2}, new int[]{0, 1, 2}, DataBuffer.TYPE_BYTE, false, false);
        PCXMetadata metadata = new PCXMetadata(rgb, header(5, PCX.COMPRESSION_RLE, 8, 3));

        Node root = standardTree(metadata);

        assertEquals("RLE", attribute(find(root, "CompressionTypeName"), "value"));
        assertEquals("LineInterleaved", attribute(find(root, "PlanarConfiguration"), "value"));
        assertEquals("5", attribute(find(root, "FormatVersion"), "value"));
    }

    private static Node standardTree(IIOMetadata metadata) {
        return metadata.getAsTree(IIOMetadataFormatImpl.standardMetadataFormatName);
    }

    private static PCXHeader header(int version, int compression, int bpp, int channels) throws IOException {
        byte[] data = PCXTestSupport.header(version, compression, bpp, 2, 1,
                PCXTestSupport.blankPalette(), channels, 2);
        try (ImageInputStream input = PCXTestSupport.input(data)) {
            input.setByteOrder(ByteOrder.LITTLE_ENDIAN);
            return PCXHeader.read(input);
        }
    }

    private static Node find(Node node, String name) {
        if (node == null) {
            return null;
        }
        if (name.equals(node.getNodeName())) {
            return node;
        }
        for (Node child = node.getFirstChild(); child != null; child = child.getNextSibling()) {
            Node found = find(child, name);
            if (found != null) {
                return found;
            }
        }
        return null;
    }

    private static String attribute(Node node, String name) {
        assertNotNull(node, "Missing metadata node");
        return node.getAttributes().getNamedItem(name).getNodeValue();
    }
}
