    @Test
    void readsSourceRegionUsingSourceCoordinates() throws IOException {
        byte[] header = PCXTestSupport.header(5, PCX.COMPRESSION_NONE, 8, 8, 4,
                PCXTestSupport.blankPalette(), 1, 8);
        byte[] body = new byte[32];
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 8; x++) {
                body[y * 8 + x] = (byte) (y * 10 + x);
            }
        }

        PCXImageReader reader = PCXTestSupport.reader(PCXTestSupport.pcx(header, body));
        try {
            ImageReadParam param = reader.getDefaultReadParam();
            param.setSourceRegion(new Rectangle(2, 1, 4, 2));

