                1, 2, 3, 4,
                5, 6, 7, 8
        };

        PCXImageReader reader = PCXTestSupport.reader(PCXTestSupport.pcx(header, body));
        try {
            BufferedImage destination = new BufferedImage(4, 2, BufferedImage.TYPE_BYTE_GRAY);
            ImageReadParam param = reader.getDefaultReadParam();
            param.setDestination(destination);

            BufferedImage result = reader.read(0, param);

            assertSame(destination, result);
            assertArrayEquals(new int[]{1, 2, 3, 4}, rowSamples(result, 0));
            assertArrayEquals(new int[]{5, 6, 7, 8}, rowSamples(result, 1));
        }
        finally {
