    }

    @Test
    void canReadTheSameImageTwice() throws IOException {
        byte[] header = PCXTestSupport.header(5, PCX.COMPRESSION_RLE, 8, 4, 1,
                PCXTestSupport.blankPalette(), 1, 4);
        byte[] body = {(byte) 0xC2, 0x11, 0x22, 0x33};

        PCXImageReader reader = PCXTestSupport.reader(PCXTestSupport.pcx(header, body));
        try {
            assertArrayEquals(new int[]{17, 17, 34, 51}, rowSamples(reader.read(0), 0));
            assertArrayEquals(new int[]{17, 17, 34, 51}, rowSamples(reader.read(0), 0));
        }
        finally {
            PCXTestSupport.dispose(reader);
        }
    }

    @Test
    void metadataDescribesRleAndPixelInterleaving() throws IOException {
        byte[] header = PCXTestSupport.header(5, PCX.COMPRESSION_RLE, 8, 4, 1,
                PCXTestSupport.blankPalette(), 1, 4);
        byte[] body = {(byte) 0xC3, 0x10, 0x20};

        PCXImageReader reader = PCXTestSupport.reader(PCXTestSupport.pcx(header, body));
        try {
            IIOMetadata metadata = reader.getImageMetadata(0);
            assertTrue(metadata.isReadOnly());

            Node root = metadata.getAsTree(IIOMetadataFormatImpl.standardMetadataFormatName);
            assertNotNull(find(root, "Compression"));
            assertEquals("RLE", attribute(find(root, "CompressionTypeName"), "value"));
            assertEquals("TRUE", attribute(find(root, "Lossless"), "value"));
            assertEquals("PixelInterleaved", attribute(find(root, "PlanarConfiguration"), "value"));
            assertEquals("5", attribute(find(root, "FormatVersion"), "value"));
        }
        finally {
            PCXTestSupport.dispose(reader);
        }
    }

    @Test
    void metadataOmitsCompressionForUncompressedRgbAndReportsLineInterleaving() throws IOException {
        byte[] header = PCXTestSupport.header(3, PCX.COMPRESSION_NONE, 8, 2, 2,
                PCXTestSupport.blankPalette(), 3, 2);
        byte[] body = new byte[12];

        PCXImageReader reader = PCXTestSupport.reader(PCXTestSupport.pcx(header, body));
        try {
            Node root = reader.getImageMetadata(0).getAsTree(IIOMetadataFormatImpl.standardMetadataFormatName);

            assertNull(find(root, "Compression"));
            assertEquals("LineInterleaved", attribute(find(root, "PlanarConfiguration"), "value"));
            assertEquals("3", attribute(find(root, "FormatVersion"), "value"));
        }
        finally {
            PCXTestSupport.dispose(reader);
        }
    }

    @Test
    void rejectsInvalidImageIndexes() throws IOException {
        byte[] header = PCXTestSupport.header(5, PCX.COMPRESSION_NONE, 8, 4, 1,
                PCXTestSupport.blankPalette(), 1, 4);
        PCXImageReader reader = PCXTestSupport.reader(PCXTestSupport.pcx(header, new byte[4]));
        try {
            assertThrows(IndexOutOfBoundsException.class, () -> reader.getWidth(-1));
            assertThrows(IndexOutOfBoundsException.class, () -> reader.getWidth(1));
            assertThrows(IndexOutOfBoundsException.class, () -> reader.getHeight(1));
            assertThrows(IndexOutOfBoundsException.class, () -> reader.getRawImageType(1));
            assertThrows(IndexOutOfBoundsException.class, () -> reader.read(1));
            assertThrows(IndexOutOfBoundsException.class, () -> reader.getImageMetadata(1));
        }
        finally {
            PCXTestSupport.dispose(reader);
        }
    }

    @Test
    void requiresInputToBeSet() {
        PCXImageReader reader = new PCXImageReader(new PCXImageReaderSpi());
        try {
            assertThrows(IllegalStateException.class, () -> reader.getWidth(0));
            assertThrows(IllegalStateException.class, () -> reader.getHeight(0));
        }
        finally {
            reader.dispose();
        }
    }

    @Test
    void readsMonochromeResourceWithDefaultBlackAndWhitePalette() throws IOException {
        PCXImageReader reader = PCXTestSupport.resourceReader("/pcx/no-palette-monochrome.pcx");
        try {
            assertEquals(128, reader.getWidth(0));
            assertEquals(152, reader.getHeight(0));

            IndexColorModel model = assertInstanceOf(IndexColorModel.class,
                    reader.getRawImageType(0).getColorModel());
            assertEquals(2, model.getMapSize());
            assertEquals(0xFF000000, model.getRGB(0));
            assertEquals(0xFFFFFFFF, model.getRGB(1));

            BufferedImage image = reader.read(0);
            assertEquals(128, image.getWidth());
            assertEquals(152, image.getHeight());
            for (int y = 0; y < image.getHeight(); y++) {
                for (int x = 0; x < image.getWidth(); x++) {
                    int rgb = image.getRGB(x, y);
                    assertTrue(rgb == 0xFF000000 || rgb == 0xFFFFFFFF,
                            "Unexpected monochrome color at " + x + "," + y + ": " + Integer.toHexString(rgb));
                }
            }
        }
        finally {
            PCXTestSupport.dispose(reader);
        }
    }

    @Test
    void readsCgaResourceWithPaletteFromHeaderFlags() throws IOException {
        PCXImageReader reader = PCXTestSupport.resourceReader("/pcx/CGA_TST1.PCX");
        try {
            assertEquals(320, reader.getWidth(0));
            assertEquals(200, reader.getHeight(0));

            IndexColorModel model = assertInstanceOf(IndexColorModel.class,
                    reader.getRawImageType(0).getColorModel());
            assertEquals(4, model.getMapSize());
            assertEquals(0xFF00AAAA, model.getRGB(0));
            assertEquals(0xFF55FFFF, model.getRGB(1));
            assertEquals(0xFFFF55FF, model.getRGB(2));
            assertEquals(0xFFFFFFFF, model.getRGB(3));

            Set<Integer> palette = new HashSet<>();
            for (int i = 0; i < model.getMapSize(); i++) {
                palette.add(model.getRGB(i));
            }

            BufferedImage image = reader.read(0);
            for (int y = 0; y < image.getHeight(); y++) {
                for (int x = 0; x < image.getWidth(); x++) {
                    assertTrue(palette.contains(image.getRGB(x, y)),
                            "Unexpected CGA color at " + x + "," + y);
                }
            }
        }
        finally {
            PCXTestSupport.dispose(reader);
        }
    }

    @Test
    void readsFourPlaneBitPlaneResource() throws IOException {
        PCXImageReader reader = PCXTestSupport.resourceReader("/pcx/rose.pcx");
        try {
            assertEquals(38, reader.getWidth(0));
            assertEquals(48, reader.getHeight(0));

            IndexColorModel model = assertInstanceOf(IndexColorModel.class,
                    reader.getRawImageType(0).getColorModel());
            assertEquals(16, model.getMapSize());

            Set<Integer> palette = new HashSet<>();
            for (int i = 0; i < model.getMapSize(); i++) {
                palette.add(model.getRGB(i));
            }

            BufferedImage image = reader.read(0);
            assertEquals(38, image.getWidth());
            assertEquals(48, image.getHeight());
            for (int y = 0; y < image.getHeight(); y++) {
                for (int x = 0; x < image.getWidth(); x++) {
                    assertTrue(palette.contains(image.getRGB(x, y)),
                            "Unexpected palette color at " + x + "," + y);
                }
            }
        }
        finally {
            PCXTestSupport.dispose(reader);
        }
    }

    @Test
    void reportsRgbResourcesAndReadsRegionFromLargeRleImage() throws IOException {
        PCXImageReader reader = PCXTestSupport.resourceReader("/pcx/MARBLES.PCX");
        try {
            assertEquals(1419, reader.getWidth(0));
            assertEquals(1001, reader.getHeight(0));
            assertEquals(3, reader.getRawImageType(0).getNumBands());

            ImageReadParam param = reader.getDefaultReadParam();
            param.setSourceRegion(new Rectangle(10, 0, 20, 10));
            BufferedImage image = reader.read(0, param);

            assertEquals(20, image.getWidth());
            assertEquals(10, image.getHeight());
            assertEquals(BufferedImage.TYPE_3BYTE_BGR, image.getType());
        }
        finally {
            PCXTestSupport.dispose(reader);
        }
    }

    @Test
    void readsEightBitRgbInputResource() throws IOException {
        PCXImageReader reader = PCXTestSupport.resourceReader("/pcx/input.pcx");
        try {
            assertEquals(70, reader.getWidth(0));
            assertEquals(46, reader.getHeight(0));

            BufferedImage image = reader.read(0);
            assertEquals(70, image.getWidth());
            assertEquals(46, image.getHeight());
            assertEquals(BufferedImage.TYPE_3BYTE_BGR, image.getType());
        }
        finally {
            PCXTestSupport.dispose(reader);
        }
    }

    private static int[] rowSamples(BufferedImage image, int y) {
        int[] samples = new int[image.getWidth()];
        for (int x = 0; x < samples.length; x++) {
            samples[x] = image.getRaster().getSample(x, y, 0);
        }
        return samples;
    }


    private static Node find(Node node, String name) {
        if (node == null) {
            return null;
        }
        if (name.equals(node.getNodeName())) {
            return node;
        }
        for (Node child = node.getFirstChild(); child != null; child = child.getNextSibling()) {
            Node found = find(child, name);
            if (found != null) {
                return found;
            }
        }
        return null;
    }

    private static String attribute(Node node, String name) {
        assertNotNull(node, "Missing metadata node");
        return node.getAttributes().getNamedItem(name).getNodeValue();
    }
}

package com.twelvemonkeys.imageio.plugins.pcx;

import com.twelvemonkeys.imageio.util.ImageTypeSpecifiers;
import org.junit.jupiter.api.Test;
import org.w3c.dom.Node;

import javax.imageio.ImageTypeSpecifier;
import javax.imageio.metadata.IIOMetadata;
import javax.imageio.metadata.IIOMetadataFormatImpl;
import javax.imageio.stream.ImageInputStream;
import java.awt.color.ColorSpace;
import java.awt.image.DataBuffer;
import java.io.IOException;
import java.nio.ByteOrder;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;

class PCXMetadataTest {

    private static final ImageTypeSpecifier GRAY =
            ImageTypeSpecifiers.createGrayscale(8, DataBuffer.TYPE_BYTE);

    @Test
    void reportsUnknownCompressionName() throws IOException {
        PCXMetadata metadata = new PCXMetadata(GRAY, header(5, 2, 8, 1));

        Node root = standardTree(metadata);

        assertEquals("Unknown", attribute(find(root, "CompressionTypeName"), "value"));
        assertEquals("TRUE", attribute(find(root, "Lossless"), "value"));
    }

    @Test
    void reportsPixelInterleavedForSingleChannelImage() throws IOException {
        PCXMetadata metadata = new PCXMetadata(GRAY, header(3, PCX.COMPRESSION_NONE, 8, 1));

        Node root = standardTree(metadata);

        assertNull(find(root, "Compression"));
        assertEquals("PixelInterleaved", attribute(find(root, "PlanarConfiguration"), "value"));
        assertEquals("3", attribute(find(root, "FormatVersion"), "value"));
    }

    @Test
    void reportsLineInterleavedForMultiChannelImage() throws IOException {
        ImageTypeSpecifier rgb = ImageTypeSpecifiers.createBanded(
                ColorSpace.getInstance(ColorSpace.CS_sRGB),
                new int[]{0, 1, 2}, new int[]{0, 1, 2}, DataBuffer.TYPE_BYTE, false, false);
        PCXMetadata metadata = new PCXMetadata(rgb, header(5, PCX.COMPRESSION_RLE, 8, 3));

        Node root = standardTree(metadata);

        assertEquals("RLE", attribute(find(root, "CompressionTypeName"), "value"));
        assertEquals("LineInterleaved", attribute(find(root, "PlanarConfiguration"), "value"));
        assertEquals("5", attribute(find(root, "FormatVersion"), "value"));
    }

    private static Node standardTree(IIOMetadata metadata) {
        return metadata.getAsTree(IIOMetadataFormatImpl.standardMetadataFormatName);
    }

    private static PCXHeader header(int version, int compression, int bpp, int channels) throws IOException {
        byte[] data = PCXTestSupport.header(version, compression, bpp, 2, 1,
                PCXTestSupport.blankPalette(), channels, 2);
        try (ImageInputStream input = PCXTestSupport.input(data)) {
            input.setByteOrder(ByteOrder.LITTLE_ENDIAN);
            return PCXHeader.read(input);
        }
    }

    private static Node find(Node node, String name) {
        if (node == null) {
            return null;
        }
        if (name.equals(node.getNodeName())) {
            return node;
        }
        for (Node child = node.getFirstChild(); child != null; child = child.getNextSibling()) {
            Node found = find(child, name);
            if (found != null) {
                return found;
            }
        }
        return null;
    }

    private static String attribute(Node node, String name) {
        assertNotNull(node, "Missing metadata node");
        return node.getAttributes().getNamedItem(name).getNodeValue();
    }
}

