/*
 * Test helper for the PCX plugin. Creates deterministic, in-memory PCX streams
 * and opens the test resources shipped with the module.
 */
package com.twelvemonkeys.imageio.plugins.pcx;

import javax.imageio.ImageIO;
import javax.imageio.stream.ImageInputStream;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.io.InputStream;
import java.net.URISyntaxException;
import java.net.URL;

final class PCXTestSupport {

    static final int HEADER_SIZE = 128;

    private PCXTestSupport() {
    }

    static byte[] header(int version, int compression, int bitsPerPixel,
                         int xStart, int yStart, int xEnd, int yEnd,
                         int hdpi, int vdpi, byte[] palette,
                         int channels, int bytesPerLine, int paletteInfo) {
        if (palette == null) {
            palette = blankPalette();
        }
        if (palette.length != 48) {
            throw new IllegalArgumentException("palette must contain exactly 48 bytes");
        }

        ByteArrayOutputStream out = new ByteArrayOutputStream(HEADER_SIZE);
        out.write(0x0A);
        out.write(version);
        out.write(compression);
        out.write(bitsPerPixel);
        writeLittleEndianShort(out, xStart);
        writeLittleEndianShort(out, yStart);
        writeLittleEndianShort(out, xEnd);
        writeLittleEndianShort(out, yEnd);
        writeLittleEndianShort(out, hdpi);
        writeLittleEndianShort(out, vdpi);
        out.write(palette, 0, palette.length);
        out.write(0); // reserved
        out.write(channels);
        writeLittleEndianShort(out, bytesPerLine);
        writeLittleEndianShort(out, paletteInfo);
        writeLittleEndianShort(out, hdpi); // horizontal screen size
        writeLittleEndianShort(out, vdpi); // vertical screen size
        while (out.size() < HEADER_SIZE) {
            out.write(0);
        }

        return out.toByteArray();
    }

    static byte[] header(int version, int compression, int bitsPerPixel,
                         int width, int height, byte[] palette,
                         int channels, int bytesPerLine) {
        return header(version, compression, bitsPerPixel,
                0, 0, width - 1, height - 1,
                width, height, palette, channels, bytesPerLine, 1);
    }

    static byte[] pcx(byte[] header, byte[] body) {
        byte[] result = new byte[header.length + body.length];
        System.arraycopy(header, 0, result, 0, header.length);
        System.arraycopy(body, 0, result, header.length, body.length);
        return result;
    }

    static byte[] blankPalette() {
        return new byte[48];
    }

    /**
     * Creates a 16-entry EGA palette from 0xRRGGBB values. Missing entries are black.
     */
    static byte[] palette(int... rgb) {
        byte[] palette = new byte[48];
        int entries = Math.min(16, rgb.length);
        for (int i = 0; i < entries; i++) {
            int value = rgb[i];
            palette[i * 3] = (byte) ((value >> 16) & 0xFF);
            palette[i * 3 + 1] = (byte) ((value >> 8) & 0xFF);
            palette[i * 3 + 2] = (byte) (value & 0xFF);
        }
        return palette;
    }

    private static void writeLittleEndianShort(ByteArrayOutputStream out, int value) {
        out.write(value & 0xFF);
        out.write((value >> 8) & 0xFF);
    }

    static ImageInputStream input(byte[] data) {
        return new javax.imageio.stream.MemoryCacheImageInputStream(new ByteArrayInputStream(data));
    }

    static ImageInputStream resourceInput(String resource) throws IOException {
        URL url = PCXTestSupport.class.getResource(resource);
        if (url == null) {
            throw new FileNotFoundException("Missing test resource: " + resource);
        }

        if ("file".equals(url.getProtocol())) {
            try {
                return ImageIO.createImageInputStream(new File(url.toURI()));
            }
            catch (URISyntaxException e) {
                throw new IOException("Bad test resource URI: " + url, e);
            }
        }

        return input(readAll(url.openStream()));
    }

    static byte[] readAll(String resource) throws IOException {
        URL url = PCXTestSupport.class.getResource(resource);
        if (url == null) {
            throw new FileNotFoundException("Missing test resource: " + resource);
        }
        return readAll(url.openStream());
    }

    private static byte[] readAll(InputStream in) throws IOException {
        try {
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            byte[] buffer = new byte[8192];
            int read;
            while ((read = in.read(buffer)) != -1) {
                out.write(buffer, 0, read);
            }
            return out.toByteArray();
        }
        finally {
            in.close();
        }
    }

    static PCXImageReader reader(byte[] data) throws IOException {
        PCXImageReader reader = new PCXImageReader(new PCXImageReaderSpi());
        reader.setInput(input(data));
        return reader;
    }

    static PCXImageReader resourceReader(String resource) throws IOException {
        PCXImageReader reader = new PCXImageReader(new PCXImageReaderSpi());
        reader.setInput(resourceInput(resource));
        return reader;
    }

    static void dispose(PCXImageReader reader) {
        if (reader != null) {
            try {
                reader.dispose();
            }
            catch (RuntimeException ignored) {
                // Best effort cleanup for tests.
            }
        }
    }
}

package com.twelvemonkeys.imageio.plugins.pcx;

import com.twelvemonkeys.io.enc.DecoderStream;
import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;

class RLEDecoderTest {

    private final RLEDecoder decoder = new RLEDecoder();

    @Test
    void decodesLiteralBytesThroughDecoderStream() throws IOException {
        assertDecoded(new int[]{0x01, 0x02, 0x7F}, stream(0x01, 0x02, 0x7F));
    }

    @Test
    void decodesCompressedRunThroughDecoderStream() throws IOException {
        assertDecoded(new int[]{0x2A, 0x2A, 0x2A}, stream(0xC3, 0x2A));
    }

    @Test
    void decodesMixedLiteralsAndRuns() throws IOException {
        assertDecoded(new int[]{0x01, 0x42, 0x42, 0x42, 0x7F}, stream(0x01, 0xC3, 0x42, 0x7F));
    }

    @Test
    void decodesZeroLengthRunThroughDecoderStream() throws IOException {
        assertDecoded(new int[0], stream(0xC0, 0x55));
    }

    @Test
    void decodesMaximumLengthRunThroughDecoderStream() throws IOException {
        int[] expected = new int[63];
        java.util.Arrays.fill(expected, 0x77);
        assertDecoded(expected, stream(0xFF, 0x77));
    }

    @Test
    void decodesLiteralWithHighBitSet() throws IOException {
        assertDecoded(new int[]{0x80, 0xBF}, stream(0x80, 0xBF));
    }

    @Test
    void decodesInputLargerThanDecoderStreamBuffer() throws IOException {
        byte[] input = new byte[2000];
        int[] expected = new int[input.length];
        for (int i = 0; i < input.length; i++) {
            input[i] = (byte) (i & 0x7F);
            expected[i] = input[i] & 0xFF;
        }

        assertDecoded(expected, new ByteArrayInputStream(input));
    }

    @Test
    void directDecodeReturnsBufferPositionAndWritesLiteral() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(64);

        int position = decoder.decode(stream(0x01), buffer);

        assertEquals(1, position);
        assertEquals(1, buffer.position());
        assertArrayEquals(new byte[]{0x01}, contents(buffer, 1));
    }

    @Test
    void directDecodeWritesWholeCompressedRun() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(64);

        int position = decoder.decode(stream(0xC3, 0x2A), buffer);

        assertEquals(3, position);
        assertArrayEquals(new byte[]{0x2A, 0x2A, 0x2A}, contents(buffer, 3));
    }

    @Test
    void directDecodeCanProduceMaximumRun() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(64);

        int position = decoder.decode(stream(0xFF, 0x77), buffer);

        assertEquals(63, position);
    }

    @Test
    void stopsAtEndOfInput() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(64);

        int position = decoder.decode(stream(), buffer);

        assertEquals(0, position);
    }

    @Test
    void stopsWhenRunMarkerIsNotFollowedByValue() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(64);

        int position = decoder.decode(stream(0xC5), buffer);

        assertEquals(0, position);
    }

    @Test
    void doesNotConsumeInputWhenLessThan64BytesRemain() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(64);
        buffer.position(1); // 63 bytes remaining

        int position = decoder.decode(stream(0xC1, 0x11), buffer);

        assertEquals(1, position);
    }

    private void assertDecoded(int[] expected, ByteArrayInputStream input) throws IOException {
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        try (InputStream decoded = new DecoderStream(input, decoder)) {
            byte[] buffer = new byte[256];
            int read;
            while ((read = decoded.read(buffer)) != -1) {
                output.write(buffer, 0, read);
            }
        }

        byte[] actual = output.toByteArray();
        assertEquals(expected.length, actual.length);
        for (int i = 0; i < expected.length; i++) {
            assertEquals(expected[i], actual[i] & 0xFF, "Byte at index " + i);
        }
    }

    private static ByteArrayInputStream stream(int... values) {
        byte[] bytes = new byte[values.length];
        for (int i = 0; i < values.length; i++) {
            bytes[i] = (byte) values[i];
        }
        return new ByteArrayInputStream(bytes);
    }

    private static byte[] contents(ByteBuffer buffer, int length) {
        byte[] result = new byte[length];
        System.arraycopy(buffer.array(), 0, result, 0, length);
        return result;
    }
}
